{"content":"package main

import (
	"fmt"
	"strings"
)

// FormatAmount renders cents as a decimal amount.
func FormatAmount(cents int64) string {
	return fmt.Sprintf("%.2f", float64(cents)/100)
}

// Total adds up every entry's amount.
func Total(entries []Entry) int64 {
	var total int64
	for _, e := range entries {
		total += e.Cents
	}
	return total
}

// FormatCSV renders entries as CSV with a header row, quoting any memo
// that contains a comma.
func FormatCSV(entries []Entry) string {
	var b strings.Builder
	b.WriteString("date,amount,memo\n")
	for _, e := range entries {
		memo := e.Memo
		if strings.Contains(memo, ",") {
			memo = `"` + memo + `"`
		}
		fmt.Fprintf(&b, "%s,%s,%s\n", e.Date.Format("2006-01-02"), FormatAmount(e.Cents), memo)
	}
	return b.String()
}
